#[test]
fn a_local_function_named_h_is_not_render_evidence() {
    let source = "function h(id: string) { return { id }; }\\n\\
        export function Hash(props: { id: string }) { return h(props.id); }";
    assert_eq!(components_in(source), Vec::<String>::new());
}

#[test]
fn a_component_passed_to_a_local_h_is_not_counted_as_rendered() {
    let source = "function h(value: unknown) { return value; }\\n\\
        function Row(props: { id: string }) { return <i />; }\\n\\
        export const rows = h(Row);";
    let data = parse_file(Utf8Path::new("/fixtures/h.tsx"), source);
    let reported: Vec<&str> = data
        .diagnostics
        .iter()
        .filter(|d| d.message.contains("'Row'"))
        .map(|d| d.message.as_str())
        .collect();
    assert_eq!(reported, Vec::<&str>::new(), "diagnostics were {:?}", data.diagnostics);
}

#[test]
fn every_element_factory_list_agrees_on_jsx_calls() {
    let source = "import { jsx } from 'react/jsx-runtime';\\n\\
        export const Card = jsx('div', { className: 'x' });\\n\\
        export function Panel(props: { id: string }) { return jsx('div', props); }";
    let data = parse_file(Utf8Path::new("/fixtures/jsx.ts"), source);
    let found: Vec<&str> = data.component_mappings.iter().map(|m| m.component_name.as_str()).collect();
    assert_eq!(found, ["Panel"]);
}

#[test]
fn preact_compat_type_import_is_react_for_the_resolver_too() {
    assert!(crate::is_react_module("preact/compat"));
    assert!(crate::is_react_module("@types/react"));
    assert!(!crate::is_react_module("preact"));
}

